#include <Arduino.h>
#include <TM1637Display.h>

TM1637Display display(4, 5);
const uint8_t lampPin = 6;
const unsigned long holdMs = 5000;
unsigned long lastMotion = 0;
unsigned long previousMs = 0;
unsigned long illuminatedMs = 0;
unsigned long lastReport = 0;
unsigned long firstSeenMs = 0;
unsigned int passages = 0;
bool haveMotion = false;
bool lampOn = false;
bool oldLeft = false;
bool oldRight = false;
uint8_t firstSide = 0;
bool waitClear = false;

void setup() {
  pinMode(2, INPUT);
  pinMode(3, INPUT);
  pinMode(lampPin, OUTPUT);
  analogWrite(lampPin, 0);
  Serial.begin(9600);
  display.setBrightness(7);
  display.showNumberDec(0);
  previousMs = millis();
}

void loop() {
  unsigned long now = millis();
  if (lampOn) illuminatedMs += now - previousMs;
  previousMs = now;
  bool left = digitalRead(2) == HIGH;
  bool right = digitalRead(3) == HIGH;
  bool riseLeft = left && !oldLeft;
  bool riseRight = right && !oldRight;

  if (waitClear) {
    if (!left && !right) waitClear = false;
  } else {
    if (firstSide && now - firstSeenMs > 10000UL) firstSide = 0;
    if (firstSide == 0) {
      if (riseLeft != riseRight) {
        firstSide = riseLeft ? 1 : 2;
        firstSeenMs = now;
      }
    } else if ((firstSide == 1 && riseRight) || (firstSide == 2 && riseLeft)) {
      ++passages;
      display.showNumberDec(passages % 10000);
      firstSide = 0;
      waitClear = true;
    }
  }
  oldLeft = left;
  oldRight = right;

  bool dark = analogRead(A0) < 512;
  if (dark && (left || right)) {
    lastMotion = now;
    haveMotion = true;
  }
  lampOn = dark && haveMotion && (now - lastMotion < holdMs);
  analogWrite(lampPin, lampOn ? 255 : 0);
  if (now - lastReport >= 1000UL) {
    lastReport = now;
    Serial.print("Illuminated milliseconds: ");
    Serial.println(illuminatedMs);
  }
}
